code.java:
public int[] countBits(int n) {
    int[] ans = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        int x = i, count = 0;
        while (x != 0) {
            x &= (x - 1);
            count++;
        }
        ans[i] = count;
    }
    return ans;
}

code.python:
def countBits(self, n: int) -> list[int]:
    ans = [0] * (n + 1)
    for i in range(n + 1):
        x, count = i, 0
        while x:
            x &= x - 1
            count += 1
        ans[i] = count
    return ans

code.java:
public int[] countBits(int n) {
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = dp[i >> 1] + (i & 1);
    }
    return dp;
}

